def mat(x, mode):
    import itertools
    terms = [()] + [(j,) for j in range(4)]
    if mode != 'linear':
        terms += list(itertools.combinations_with_replacement(range(4), 2))
        terms += [(j, j, j) for j in range(4)] if mode == 'owncubic' else list(itertools.combinations_with_replacement(range(4), 3)) if mode == 'cubic' else []
    return (np.array([x[:, p].prod(1) for p in terms]).T, terms)

def fit(a, z):
    b = np.linalg.lstsq(a, z, rcond=None)[0]
    for s in (0.8, 0.2, 0.06, 0.02, 0.006, 0.002, 0.0006):
        if len(a) < a.shape[1] + 4:
            break
        for _ in range(16):
            w = (1 + np.sum(((a @ b - z) / s) ** 2, axis=1)) ** (-0.5)
            b = np.linalg.lstsq(a * w[:, None], z * w[:, None], rcond=None)[0]
    return b

def _features(train, test=None, *, balanced=True):
    blocks = (train,) if test is None else (train, test)

    def stack(key):
        return np.concatenate([b[key] for b in blocks])
    (lab, stratum) = (stack('lab_id'), stack('stratum'))
    x = stack('coupon_features_raw').astype(float, copy=True)
    ref = stack('ref_coupons')
    for group in np.unique(lab):
        mask = lab == group
        panel = ref[mask]
        loc = np.median(panel.mean(axis=0))
        scale = np.median(panel.std(axis=0))
        x[mask] = (x[mask] - loc) / (scale if scale > 0 else 1.0)
    if balanced:
        (_, ix, counts) = np.unique(np.column_stack((lab, stratum)), axis=0, return_inverse=True, return_counts=True)
        weight = (1.0 / counts[ix])[:, None]
    else:
        weight = np.ones((len(lab), 1))
    den = (weight * np.isfinite(x)).sum(axis=0)
    fill = np.divide(np.nansum(weight * x, axis=0), den, out=np.zeros(x.shape[1]), where=den > 0)
    x = np.where(np.isfinite(x), x, fill)
    return (x,) if test is None else np.split(x, [len(train['lab_id'])])

def _kernel(dt, tau):
    tail = np.cumsum(dt[::-1])[::-1] - dt
    return -np.expm1(-dt[:, None] / tau) * np.exp(-tail[:, None] / tau)

def _predict(inp, dt, t, tau, theta):
    (past, hold, x) = inp
    gap = hold[:, None] - past @ _kernel(dt, tau)
    amp = gap * theta[:2]
    drift = x @ theta[2:]
    return (amp @ (-np.expm1(-t[:, None] / tau)).T + drift[:, None] * t, amp @ (1 / tau) + drift)

def _material(block, inp, dt, t, subset=None):
    from scipy.optimize import least_squares
    ind = slice(None) if subset is None else subset
    inputs = tuple((a[ind] for a in inp))
    y = block['strain_curves_obs'][ind] - block['strain_0'][ind, None]
    r = block['instant_rate_obs'][ind]

    def unpack(v):
        return (np.array([v[0], v[0] + (25.0 - v[0]) * v[1]]), v[2:])

    def resid(v, scale):
        (cy, cr) = _predict(inputs, dt, t, *unpack(v))
        return np.r_[((cy - y) / scale[0]).ravel(), (cr - r) / scale[1]]
    bounds = ([0.050001, 1e-06] + [-np.inf] * 7, [24.999, 0.999999] + [np.inf] * 7)
    best = None
    for (a, b) in ((0.25, 2.0), (0.8, 5.0), (2.0, 12.0)):
        v = np.r_[a, (b - a) / (25 - a), 0.4, 0.7, 0.1, np.zeros(4)]
        fit = least_squares(resid, v, args=((0.035, 0.06),), bounds=bounds, loss='soft_l1', x_scale='jac', max_nfev=150)
        if best is None or fit.cost < best.cost:
            best = fit
    e = resid(best.x, (1.0, 1.0))

    def mad(q):
        return max(1e-05, 1.4826 * np.median(np.abs(q - np.median(q))))
    s = (mad(e[:y.size]), mad(e[y.size:]))
    fit = least_squares(resid, best.x, args=(s,), bounds=bounds, loss='cauchy', f_scale=2.385, x_scale='jac', max_nfev=130)
    return (*unpack(fit.x), s)

def _chamber_design(inp, dt, t, tau, theta, memory, drift):
    """Each column is a strain correction with its matching initial derivative."""
    (past, hold, x) = inp
    n = len(hold)
    basis = np.vstack((-np.expm1(-t[:, None] / tau), 1 / tau))
    weights = _kernel(dt, tau)
    amps = (hold[:, None] - past @ weights) * theta[:2]
    ramp = np.r_[t, 1.0]
    nominal_drift = x @ theta[2:]
    columns = []

    def add(z, envelope):
        columns.append(z[:, None] * envelope)

    def branch(z):
        columns.append(z @ basis.T)
    if memory == 'offset':
        for j in range(2):
            add(np.ones(n), basis[:, j])
    elif memory == 'initial':
        for z in (np.ones(n), past[:, 0]):
            branch(z[:, None] * (theta[:2] * np.exp(-dt.sum() / tau)))
    elif memory == 'gain':
        branch(past @ weights * theta[:2])
        branch(amps)
    elif memory == 'order':
        branch((past[:, ::-1] - past) @ weights * theta[:2])
    elif isinstance(memory, float):
        branch(past @ (_kernel(dt * memory, tau) - weights) * theta[:2])
    elif memory == 'kernel':
        for j in range(len(dt)):
            branch(past[:, j, None] * weights[j] * theta[:2])
    if drift == 'linear':
        add(np.ones(n), ramp)
        add(nominal_drift, ramp)
    elif drift == 'features':
        for z in x.T:
            add(z, ramp)
    elif drift is not None:
        if drift == 'quadratic':
            curvature = np.r_[t ** 2 / max(t[-1], 1e-08), 0.0]
        else:
            curvature = np.r_[-drift * np.expm1(-t / drift), 1.0]
        add(nominal_drift, curvature - ramp)
        add(nominal_drift, ramp)
        add(np.ones(n), curvature - ramp)
        add(np.ones(n), ramp)
    if not columns:
        return np.empty((n, len(t) + 1, 0))
    return np.stack(columns, axis=-1)
